  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: oklch(0.985 0.007 170);
      --surface: oklch(0.998 0.002 180);
      --surface-soft: oklch(0.97 0.01 175);
      --text: oklch(0.24 0.03 200);
      --muted: oklch(0.5 0.02 205);
      --primary: oklch(0.6 0.11 185);
      --primary-deep: oklch(0.5 0.12 186);
      --accent: oklch(0.76 0.15 45);
