      --shadow: 0 10px 30px oklch(0.3 0.03 200 / 0.08);
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Inter, system-ui, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, oklch(0.99 0.006 170), oklch(0.975 0.01 180));
      line-height: 1.55;
    }
    .container { width: min(1180px, 92vw); margin: 0 auto; }
    .top-ticker {
      background: linear-gradient(90deg, oklch(0.56 0.13 184), oklch(0.54 0.1 170));
      color: #fff;
      padding: 12px 0;
      overflow: hidden;
      position: relative;
    }
    .ticker-track {
      display: flex;
      gap: 48px;
      width: max-content;
      animation: ticker 24s linear infinite;
      font-weight: 600;
      letter-spacing: .01em;
      white-space: nowrap;
    }
    @keyframes ticker { from { transform: translateX(0);} to { transform: translateX(-50%);} }

    header {
      background: color-mix(in oklab, var(--surface) 92%, white);
      border-bottom: 1px solid var(--border);
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(8px);
