      font: inherit; padding: 10px 12px; border-radius: 10px; cursor: pointer; font-weight: 600;
    }
    .nav-btn:hover, .nav-btn.active { background: var(--surface-soft); }

    .mega {
      position: absolute; left: 50%; transform: translateX(-50%);
      top: 64px; width: min(980px, 94vw);
      background: var(--surface); border: 1px solid var(--border); border-radius: 16px;
      box-shadow: var(--shadow); padding: 18px; display: none;
      grid-template-columns: repeat(3, 1fr); gap: 14px;
    }
    .mega.open { display: grid; }
    .mega h4 { margin: 0 0 8px; font-size: .95rem; color: var(--primary-deep); }
    .mega a { display: block; text-decoration: none; color: var(--text); padding: 8px 10px; border-radius: 10px; }
    .mega a:hover { background: var(--surface-soft); }

    .hero { padding: 48px 0 24px; display: grid; grid-template-columns: 1.5fr .9fr; gap: 20px; }
    .hero-main {
      background: var(--surface); border: 1px solid var(--border); border-radius: 24px; padding: 28px;
      box-shadow: var(--shadow);
    }
    .eyebrow { color: var(--primary-deep); font-weight: 700; letter-spacing: .03em; text-transform: uppercase; font-size: .78rem; }
    h1 { margin: 10px 0 10px; font-size: clamp(1.8rem, 3.6vw, 3rem); line-height: 1.12; }
    .lead { color: var(--muted); font-size: 1.06rem; }
    .btn {
      border: 0; border-radius: 12px; padding: 12px 16px; font-weight: 700; cursor: pointer;
      transition: transform .18s ease, box-shadow .18s ease;
    }
    .btn:hover { transform: translateY(-2px); }
    .btn-primary { background: var(--accent); color: oklch(0.25 0.03 55); }
    .btn-ghost { background: var(--surface-soft); color: var(--text); }

    .panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); }
    .panel h3 { margin: 0 0 12px; }
    .trending-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
    .trending-list li { padding: 10px; border-radius: 12px; background: var(--surface-soft); }
    .tag { display: inline-block; font-size: .73rem; color: var(--primary-deep); font-weight: 700; margin-bottom: 4px; }

    section { padding: 18px 0; }
    .newsletter {
      margin-top: 8px;
      background: linear-gradient(120deg, oklch(0.88 0.06 180), oklch(0.89 0.08 60));
      border: 1px solid color-mix(in oklab, var(--primary) 25%, white);
      border-radius: 20px; padding: 24px;
      display: grid; grid-template-columns: 1.2fr 1fr; gap: 18px; align-items: center;
    }
    .newsletter form { display: flex; gap: 10px; }
    input[type="email"] {
      width: 100%; border: 1px solid var(--border); border-radius: 12px; padding: 12px 13px; font: inherit;
    }

    .topics-head, .tabs-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
    .carousel-wrap { position: relative; }
    .topics-row {
      display: grid; grid-auto-flow: column; grid-auto-columns: minmax(130px, 1fr);
      overflow-x: auto; gap: 12px; padding-bottom: 8px; scroll-behavior: smooth;
    }
    .topic { background: var(--surface); border: 1px solid var(--border); border-radius: 16px; padding: 12px; text-align: center; min-height: 160px; }
    .topic img { width: 78px; height: 78px; border-radius: 999px; object-fit: cover; border: 3px solid oklch(0.9 0.02 175); }
    .arrow { width: 38px; height: 38px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface); cursor: pointer; }

    .tools-grid, .reads-grid, .pillar-grid, .programs-grid, .videos-grid { display: grid; gap: 14px; }
    .tools-grid { grid-template-columns: repeat(3, 1fr); }
    .tool-card, .read-card, .pillar, .program, .video {
      background: var(--surface); border: 1px solid var(--border); border-radius: 16px; padding: 16px; box-shadow: var(--shadow);
    }
    .tabs { display: flex; gap: 8px; flex-wrap: wrap; }
    .tab {
      border: 1px solid var(--border); background: var(--surface); color: var(--text);
      padding: 9px 12px; border-radius: 999px; cursor: pointer; font-weight: 600;
    }
    .tab.active { background: color-mix(in oklab, var(--primary) 14%, white); border-color: color-mix(in oklab, var(--primary) 40%, white); }
    .reads-grid { grid-template-columns: repeat(4, 1fr); }

    .trust {
      background: linear-gradient(180deg, oklch(0.96 0.02 180), oklch(0.97 0.01 175));
      border: 1px solid var(--border); border-radius: 20px; padding: 24px;
    }
    .pillar-grid { grid-template-columns: repeat(4, 1fr); }
    .programs-grid, .videos-grid { grid-template-columns: repeat(3, 1fr); }

    footer { margin-top: 22px; padding: 24px 0 36px; color: var(--muted); font-size: .95rem; }

    @media (max-width: 980px) {
      .hero, .newsletter { grid-template-columns: 1fr; }
      .tools-grid, .reads-grid, .pillar-grid, .programs-grid, .videos-grid { grid-template-columns: repeat(2, 1fr); }
      .mega { top: 110px; grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 640px) {
      .tools-grid, .reads-grid, .pillar-grid, .programs-grid, .videos-grid { grid-template-columns: 1fr; }
      .mega { grid-template-columns: 1fr; }
    }
