  <footer>
    <div class="container">© 2026 WellSource Media. Evidence-based health guidance for everyday decisions.</div>
  </footer>

  <script>
    const megaData = {
      conditions: {
        title: 'Health Conditions',
        cols: [
          {h:'Common Conditions', links:['Heart Health','Type 2 Diabetes','Digestive Health','Skin Conditions']},
          {h:'Symptoms & Tests', links:['Symptom Checker','Lab Test Guide','When to See a Doctor']},
          {h:'Care Guides', links:['Medication Basics','Treatment Plans','Recovery Timelines']}
        ]
      },
      wellness: {
        title: 'Wellness',
        cols: [
          {h:'Mind & Body', links:['Mental Well-Being','Sleep','Stress Management']},
          {h:'Nutrition', links:['Healthy Eating','Supplements','Recipes']},
          {h:'Lifestyle', links:['Fitness','Work-Life Health','Aging Well']}
        ]
      },
      tools: {
        title: 'Tools',
        cols: [
          {h:'Calculators', links:['Macronutrient Calculator','Calorie Calculator','BMI Tool']},
          {h:'Medication', links:['Drug Directory A-Z','Pill Identifier','Interaction Checker']},
          {h:'Care', links:['FindCare','Insurance Basics','Appointment Prep']}
        ]
      },
      featured: {
        title: 'Featured',
        cols: [
          {h:'Editor Picks', links:['Top Reads','Expert Columns','Weekly Roundup']},
          {h:'Seasonal', links:['Spring Allergies','Summer Skin Care','Holiday Wellness']},
          {h:'Programs', links:['Heart Reset','Sleep Blueprint','Move Every Day']}
        ]
      },
      connect: {
        title: 'Connect',
        cols: [
          {h:'Community', links:['Health Forums','Member Stories','Ask an Expert']},
          {h:'Newsletters', links:['Daily Brief','Condition-Specific Updates','Product Roundups']},
          {h:'About', links:['Editorial Policy','Medical Review Board','Contact Us']}
        ]
      }
    };

    const navButtons = [...document.querySelectorAll('.nav-btn')];
    const megaMenu = document.getElementById('megaMenu');
    let activeMenu = null;

    function renderMega(menuKey){
      const data = megaData[menuKey];
      megaMenu.innerHTML = data.cols.map(col => `
        <div>
          <h4>${col.h}</h4>
          ${col.links.map(link=>`<a href="index.html">${link}</a>`).join('')}
        </div>`).join('');
    }

    navButtons.forEach(btn=>{
      btn.addEventListener('click', () => {
        const key = btn.dataset.menu;
        if(activeMenu === key){
          activeMenu = null;
          megaMenu.classList.remove('open');
          navButtons.forEach(b=>b.classList.remove('active'));
          return;
        }
        activeMenu = key;
        renderMega(key);
        megaMenu.classList.add('open');
        navButtons.forEach(b=>b.classList.toggle('active', b===btn));
      });
    });

    document.addEventListener('click', (e)=>{
      if(!e.target.closest('header')){
        megaMenu.classList.remove('open');
        navButtons.forEach(b=>b.classList.remove('active'));
        activeMenu = null;
      }
    });

    const topicsRow = document.getElementById('topicsRow');
    document.getElementById('topicsLeft').addEventListener('click', ()=>topicsRow.scrollBy({left:-260,behavior:'smooth'}));
    document.getElementById('topicsRight').addEventListener('click', ()=>topicsRow.scrollBy({left:260,behavior:'smooth'}));

    const tabs = ['Top Reads','Fitness','Mental Well-Being','Product Reviews','Recipes','Skin Care'];
    const readsData = {
      'Top Reads': [
        '16 Superfoods That Are Worthy of the Title',
        'Does Ozempic Cause Hair Loss?',
        'Can Music Therapy Help with Depression?',
        'These Are the 8 Best Calorie Counter Apps'
      ],
      'Fitness': [
        'How to Start Strength Training After 40',
        'Walking Workouts That Actually Build Endurance',
        'Can You Run a Marathon ... with POTS?',
        'Mobility Moves for Desk Workers'
      ],
      'Mental Well-Being': [
        'Can Music Therapy Help with Depression?',
        '5 Grounding Techniques for High-Stress Days',
        'A Therapist’s Guide to Better Boundaries',
        'How Sleep and Anxiety Influence Each Other'
      ],
      'Product Reviews': [
        'These Are the 8 Best Calorie Counter Apps',
        'Is Floor Sitting the New Standing? This Unique Desk Surprised Us',
        'Our Favorite Meal-Prep Containers for 2026',
        'Top Wearables for Heart Health Tracking'
      ],
      'Recipes': [
        'How to Make a Heart-Healthy Grocery List',
        '12 High-Protein Breakfasts in 15 Minutes',
        'Anti-Inflammatory Dinner Bowl Formula',
        'No-Cook Lunches for Busy Weekdays'
      ],
      'Skin Care': [
        'Dermatologist Tips for Spring Skin',
        'Does Ozempic Cause Hair Loss?',
        'SPF Myths You Should Stop Believing',
        'Building a Gentle Routine for Sensitive Skin'
      ]
    };

    const tabsWrap = document.getElementById('readTabs');
    const readsGrid = document.getElementById('readsGrid');

    function renderReads(category){
      readsGrid.innerHTML = readsData[category].map((title, idx)=>`
        <article class="read-card">
          <span class="tag">${category}</span>
          <h3 style="margin:6px 0 8px; font-size:1rem; line-height:1.35">${title}</h3>
          <p style="margin:0; color:var(--muted)">Doctor-reviewed guidance with practical next steps.</p>
        </article>`).join('');
      [...tabsWrap.children].forEach(btn => btn.classList.toggle('active', btn.dataset.tab===category));
    }

    tabs.forEach((tab, i)=>{
      const btn = document.createElement('button');
      btn.className = 'tab' + (i===0 ? ' active':'');
      btn.textContent = tab;
      btn.dataset.tab = tab;
      btn.addEventListener('click', ()=>renderReads(tab));
      tabsWrap.appendChild(btn);
    });
    renderReads('Top Reads');

    document.getElementById('newsletterForm').addEventListener('submit', (e)=>{
      e.preventDefault();
      const email = document.getElementById('emailInput').value.trim();
      if(!email) return;
      alert(`Thanks for joining WellSource, ${email}!`);
      e.target.reset();
    });
  </script>
</body>
</html>
