      ]
    };

    const tabsWrap = document.getElementById('readTabs');
    const readsGrid = document.getElementById('readsGrid');

    function renderReads(category){
      readsGrid.innerHTML = readsData[category].map((title, idx)=>`
        <article class="read-card">
          <span class="tag">${category}</span>
          <h3 style="margin:6px 0 8px; font-size:1rem; line-height:1.35">${title}</h3>
          <p style="margin:0; color:var(--muted)">Doctor-reviewed guidance with practical next steps.</p>
        </article>`).join('');
      [...tabsWrap.children].forEach(btn => btn.classList.toggle('active', btn.dataset.tab===category));
    }

    tabs.forEach((tab, i)=>{
      const btn = document.createElement('button');
      btn.className = 'tab' + (i===0 ? ' active':'');
      btn.textContent = tab;
      btn.dataset.tab = tab;
      btn.addEventListener('click', ()=>renderReads(tab));
      tabsWrap.appendChild(btn);
    });
